get_dashboard_kpi_options.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.dashboardKpis().getDashboardKpiOptions();
Map<?, ?> body = (Map<?, ?>) response.getMap();
System.out.println(body.get("min") + " " + body.get("max") + " " + body.get("selected"));
for (Object row : (List<?>) body.get("groups")) {
    Map<?, ?> group = (Map<?, ?>) row;
    System.out.println(group.get("key") + " " + group.get("label"));
}

get_dashboard_kpi_selection.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.dashboardKpis().getDashboardKpiSelection(Map.of("duration", "last_7_days"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("selected")) {
    Map<?, ?> kpi = (Map<?, ?>) row;
    System.out.println(kpi.get("key") + " " + kpi.get("value") + " " + kpi.get("change_percent") + " " + kpi.get("direction"));
}

